.result-card {
  display: none;
  margin-top: 2rem;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem;
  text-align: center;
}
.result-card.visible { display: block; }
.result-score {
  font-size: clamp(2rem, 8vw, 3rem);
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -.03em;
}
.result-label {
  margin-top: .25rem;
  font-size: 1.0625rem;
  color: var(--color-text-muted);
}
.result-detail {
  margin-top: 1.25rem;
  font-size: .9375rem;
  color: var(--color-text);
  text-align: left;
  border-top: 1px solid var(--color-border);
  padding-top: 1.25rem;
}
.result-detail li {
  margin-bottom: .5rem;
  list-style: none;
  padding-left: 1.5rem;
