+main {
+  max-width: 640px;
+  margin-inline: auto;
+}
+
+/* ── Quiz form card ─────────────────────────────────────────── */
+.quiz-card {
+  background: var(--color-surface);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-card);
+  padding: 2rem;
+}
+
+/* ── form-field wrapper ─────────────────────────────────────── */
+.form-field {
+  padding: 1.5rem 0;
+  border-bottom: 1px solid var(--color-border);
+}
+.form-field:first-of-type { padding-top: 0; }
+.form-field:last-of-type  { border-bottom: none; padding-bottom: 0; }
+
+/* ── fieldset / legend ──────────────────────────────────────── */
+fieldset {
+  border: none;
+  padding: 0;
+  min-width: 0;
+}
+
+legend {
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--color-text);
+  padding: 0;
+  margin-bottom: .5rem;
+  line-height: 1.4;
+  float: left;           /* classic legend float trick for full-width layout */
+  width: 100%;
+}
+legend + * { clear: both; }
+
+.question-number {
+  display: inline-block;
+  font-size: .6875rem;
+  font-weight: 700;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  color: var(--color-primary);
+  background: var(--color-check-bg);
+  border-radius: 99px;
+  padding: .125rem .625rem;
+  margin-bottom: .375rem;
+}
+
+/* ── Help / error text ──────────────────────────────────────── */
+.help-text {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  margin-bottom: .875rem;
+  line-height: 1.5;
+}
+
+.error-text {
+  display: none;
+  font-size: .875rem;
+  color: var(--color-error);
+  background: var(--color-error-bg);
+  border: 1px solid var(--color-error-border);
+  border-radius: var(--radius-sm);
+  padding: .5rem .75rem;
+  margin-top: .75rem;
+}
+.error-text[aria-hidden="false"],
+.error-text:not([hidden]) { display: block; }
+
+/* ── Checkbox options ───────────────────────────────────────── */
+.options {
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+}
+
+.option {
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+  padding: .625rem .875rem;
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-md);
+  cursor: pointer;
+  transition: border-color var(--transition), background var(--transition);
+  user-select: none;
+}
+.option:hover {
+  border-color: var(--color-primary);
+  background: var(--color-check-bg);
+}
+
+/* Keyboard focus on the hidden checkbox → visible ring on the label */
+.option input[type="checkbox"] {
+  appearance: none;
+  -webkit-appearance: none;
+  width: 1.125rem;
+  height: 1.125rem;
+  flex-shrink: 0;
+  border: 2px solid var(--color-border);
+  border-radius: 4px;
+  background: #fff;
+  cursor: pointer;
+  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
+  position: relative;
+}
+.option input[type="checkbox"]:focus-visible {
+  outline: 3px solid var(--color-border-focus);
+  outline-offset: 2px;
+}
+.option input[type="checkbox"]:checked {
+  background: var(--color-primary);
+  border-color: var(--color-primary);
+}
+.option input[type="checkbox"]:checked::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 12 10' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 5l3.5 3.5L11 1' stroke='%23fff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' fill='none'/%3E%3C/svg%3E") center/70% no-repeat;
+}
+
+/* Checked state on the label row */
+.option:has(input[type="checkbox"]:checked) {
+  border-color: var(--color-primary);
+  background: var(--color-check-bg);
