AssistantMessageToolRequest(name='create', tool_call_id='tooluse_S0TzzKWMhezkPsdRTYjvBq', arguments={'file_text': '(function () {
  "use strict";

  /* ── Answer key ─────────────────────────────────────────────
     Each value is the set of checkbox values that must ALL be
     checked (and only those) for a "correct" answer.
  ──────────────────────────────────────────────────────────── */
  const ANSWER_KEY = {
    q1: ["java", "cpp"],
    q2: ["javascript", "typescript"],
    q3: ["java", "go"],
  };

  const form = document.getElementById("quiz-form");
  const statusEl = document.getElementById("quiz-status");
  const resultCard = document.getElementById("result-card");

  /* ── Helpers ────────────────────────────────────────────── */
  function getCheckedValues(name) {
    return Array.from(
      form.querySelectorAll(`input[name="${name}"]:checked`)
    ).map((cb) => cb.value);
  }

  function setGroupError(fieldset, errorEl, message) {
    errorEl.textContent = message;
    errorEl.removeAttribute("hidden");
    fieldset.setAttribute("aria-invalid", "true");
    // keep aria-describedby in sync (help text id may already be there)
    const existing = (fieldset.getAttribute("aria-describedby") || "")
      .split(" ")
      .filter(Boolean);
    if (!existing.includes(errorEl.id)) {
      fieldset.setAttribute(
        "aria-describedby",
        [...existing, errorEl.id].join(" ")
      );
    }
  }

  function clearGroupError(fieldset, errorEl) {
    errorEl.textContent = "";
    errorEl.setAttribute("hidden", "");
    fieldset.removeAttribute("aria-invalid");
    // remove error id from aria-describedby
    const ids = (fieldset.getAttribute("aria-describedby") || "")
      .split(" ")
      .filter((id) => id && id !== errorEl.id);
    if (ids.length) {
      fieldset.setAttribute("aria-describedby", ids.join(" "));
    } else {
      fieldset.removeAttribute("aria-describedby");
    }
  }

  /* Clear error as soon as the user picks something ────────── */
  form.querySelectorAll("fieldset[data-question]").forEach((fs) => {
    const errorEl = document.getElementById(fs.dataset.errorId);
    fs.addEventListener("change", () => {
      if (errorEl && getCheckedValues(fs.dataset.question).length > 0) {
        clearGroupError(fs, errorEl);
      }
    });
  });

  /* ── Submit ─────────────────────────────────────────────── */
  form.addEventListener("submit", (e) => {
    e.preventDefault();

    // Reset status
    statusEl.className = "";
    statusEl.textContent = "";
    statusEl.style.display = "none";
    resultCard.classList.remove("visible");

    let firstInvalidFieldset = null;
    let allValid = true;

    // Validate each group
    form.querySelectorAll("fieldset[data-question]").forEach((fs) => {
      const qName = fs.dataset.question;
      const errorEl = document.getElementById(fs.dataset.errorId);
      const checked = getCheckedValues(qName);

      if (checked.length === 0) {
        allValid = false;
        setGroupError(fs, errorEl, "Error: Select at least one answer.");
        if (!firstInvalidFieldset) firstInvalidFieldset = fs;
      } else {
        if (errorEl) clearGroupError(fs, errorEl);
      }
    });

    if (!allValid) {
      // Move focus to first invalid group's first checkbox
      const firstCb = firstInvalidFieldset.querySelector(
        'input[type="checkbox"]'
      );
      if (firstCb) firstCb.focus();

      statusEl.textContent =
        "Please answer all questions before submitting.";
      statusEl.className = "error";
      statusEl.style.display = "block";
      return;
    }

    // Score
    let correct = 0;
    const details = [];
    Object.entries(ANSWER_KEY).forEach(([qName, correctValues]) => {
      const chosen = getCheckedValues(qName).sort();
      const expected = [...correctValues].sort();
      const isCorrect =
        chosen.length === expected.length &&
        chosen.every((v, i) => v === expected[i]);
      if (isCorrect) correct++;
      details.push({ qName, isCorrect });
    });

    const total = Object.keys(ANSWER_KEY).length;

    // Announce result
    statusEl.textContent = `Quiz submitted! You got ${correct} out of ${total} correct.`;
    statusEl.className = correct === total ? "success" : "error";
    statusEl.style.display = "block";

    // Build result card
    renderResult(correct, total, details);
    resultCard.classList.add("visible");
    resultCard.focus();
  });

  /* ── Render result card ─────────────────────────────────── */
  const QUESTION_LABELS = {
    q1: "Q1: Statically typed languages",
    q2: "Q2: Web frontend languages",
    q3: "Q3: Garbage-collected languages",
  };

  function renderResult(correct, total, details) {
    document.getElementById("result-score").textContent =
      `${correct} / ${total}`;
    document.getElementById("result-label").textContent =
      correct === total
        ? "Perfect score! 🎉"
        : correct === 0
        ? "Better luck next time!"
        : "Good effort — review the answers below.";

    const list = document.getElementById("result-detail-list");
    list.innerHTML = "";
    details.forEach(({ qName, isCorrect }) => {
      const li = document.createElement("li");
      if (!isCorrect) li.className = "wrong";
      li.textContent = QUESTION_LABELS[qName];
      list.appendChild(li);
    });
  }
})();
