  --font-sans:          -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --transition:         150ms ease;
}

/* ── Screen-reader only ─────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 200;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-family: var(--font-sans);
  font-size: .875rem;
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Base ───────────────────────────────────────────────────── */
body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  min-height: 100dvh;
  padding: 2rem 1rem 4rem;
}

/* ── Page layout ────────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2rem;
}
.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}
.page-header p {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: .9375rem;
}

main {
  max-width: 640px;
  margin-inline: auto;
}

/* ── Quiz form card ─────────────────────────────────────────── */
.quiz-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem;
}

/* ── form-field wrapper ─────────────────────────────────────── */
.form-field {
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--color-border);
}
.form-field:first-of-type { padding-top: 0; }
.form-field:last-of-type  { border-bottom: none; padding-bottom: 0; }

/* ── fieldset / legend ──────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  padding: 0;
  margin-bottom: .5rem;
  line-height: 1.4;
  float: left;           /* classic legend float trick for full-width layout */
  width: 100%;
}
legend + * { clear: both; }

.question-number {
  display: inline-block;
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: var(--color-check-bg);
  border-radius: 99px;
  padding: .125rem .625rem;
  margin-bottom: .375rem;
}

/* ── Help / error text ──────────────────────────────────────── */
.help-text {
  font-size: .875rem;
  color: var(--color-text-muted);
  margin-bottom: .875rem;
  line-height: 1.5;
}

.error-text {
  display: none;
  font-size: .875rem;
  color: var(--color-error);
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  border-radius: var(--radius-sm);
  padding: .5rem .75rem;
  margin-top: .75rem;
}
.error-text[aria-hidden="false"],
.error-text:not([hidden]) { display: block; }

/* ── Checkbox options ───────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.option {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .625rem .875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  user-select: none;
}
.option:hover {
  border-color: var(--color-primary);
  background: var(--color-check-bg);
}

/* Keyboard focus on the hidden checkbox → visible ring on the label */
.option input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  flex-shrink: 0;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  position: relative;
}
.option input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}
.option input[type="checkbox"]:checked {
  background: var(--color-primary);
  border-color: var(--color-primary);
}
.option input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg viewBox='0 0 12 10' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 5l3.5 3.5L11 1' stroke='%23fff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' fill='none'/%3E%3C/svg%3E") center/70% no-repeat;
}

/* Checked state on the label row */
.option:has(input[type="checkbox"]:checked) {
  border-color: var(--color-primary);
  background: var(--color-check-bg);
}

/* Invalid state */
fieldset[aria-invalid="true"] .option {
  border-color: var(--color-error-border);
}
fieldset[aria-invalid="true"] .option:has(input[type="checkbox"]:checked) {
  border-color: var(--color-primary);
  background: var(--color-check-bg);
}

.option-label {
  font-size: .9375rem;
  color: var(--color-text);
  cursor: pointer;
  line-height: 1.4;
}

/* ── Submit button ──────────────────────────────────────────── */
.form-actions {
  margin-top: 1.75rem;
  display: flex;
  justify-content: flex-end;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.75rem;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
}
.btn-submit:hover  { background: var(--color-primary-dark); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}
.btn-submit:active { transform: scale(.98); }

/* ── Status / result ────────────────────────────────────────── */
#quiz-status {
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  display: none;
}
#quiz-status.success {
  display: block;
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
  color: var(--color-success-text);
}
#quiz-status.error {
  display: block;
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  color: var(--color-error);
}

/* ── Result score card ──────────────────────────────────────── */
.result-card {
  display: none;
  margin-top: 2rem;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem;
  text-align: center;
}
.result-card.visible { display: block; }
.result-score {
  font-size: clamp(2rem, 8vw, 3rem);
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -.03em;
}
.result-label {
  margin-top: .25rem;
  font-size: 1.0625rem;
  color: var(--color-text-muted);
}
.result-detail {
  margin-top: 1.25rem;
  font-size: .9375rem;
  color: var(--color-text);
  text-align: left;
  border-top: 1px solid var(--color-border);
  padding-top: 1.25rem;
}
.result-detail li {
  margin-bottom: .5rem;
  list-style: none;
  padding-left: 1.5rem;
  position: relative;
}
.result-detail li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: #16a34a;
  font-weight: 700;
}
.result-detail li.wrong::before {
  content: "✗";
  color: var(--color-error);
}

/* ── Forced colors (high contrast) ─────────────────────────── */
@media (forced-colors: active) {
  .option { border-color: ButtonText; }
  .option:has(input[type="checkbox"]:checked) { border-color: Highlight; }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonText; }
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow (narrow) ────────────────────────────────────────── */
@media (max-width: 400px) {
  .quiz-card { padding: 1.25rem 1rem; }
  .form-actions { justify-content: stretch; }
  .btn-submit { width: 100%; justify-content: center; }
}
