  background: var(--color-primary);
  color: #fff;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
}
.btn-submit:hover  { background: var(--color-primary-dark); }
.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}
.btn-submit:active { transform: scale(.98); }

/* ── Status / result ────────────────────────────────────────── */
#quiz-status {
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  display: none;
}
#quiz-status.success {
  display: block;
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
  color: var(--color-success-text);
}
#quiz-status.error {
  display: block;
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  color: var(--color-error);
}

/* ── Result score card ──────────────────────────────────────── */
.result-card {
  display: none;
  margin-top: 2rem;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem;
  text-align: center;
}
.result-card.visible { display: block; }
.result-score {
  font-size: clamp(2rem, 8vw, 3rem);
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -.03em;
}
.result-label {
  margin-top: .25rem;
  font-size: 1.0625rem;
  color: var(--color-text-muted);
}
.result-detail {
  margin-top: 1.25rem;
  font-size: .9375rem;
  color: var(--color-text);
  text-align: left;
  border-top: 1px solid var(--color-border);
  padding-top: 1.25rem;
}
.result-detail li {
  margin-bottom: .5rem;
  list-style: none;
  padding-left: 1.5rem;
  position: relative;
}
.result-detail li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: #16a34a;
  font-weight: 700;
}
.result-detail li.wrong::before {
  content: "✗";
  color: var(--color-error);
}

/* ── Forced colors (high contrast) ─────────────────────────── */
@media (forced-colors: active) {
  .option { border-color: ButtonText; }
  .option:has(input[type="checkbox"]:checked) { border-color: Highlight; }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonText; }
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow (narrow) ────────────────────────────────────────── */
@media (max-width: 400px) {
  .quiz-card { padding: 1.25rem 1rem; }
  .form-actions { justify-content: stretch; }
  .btn-submit { width: 100%; justify-content: center; }
}
